mapper.update:
UPDATE loan
SET due_at      = #{dueAt},
    renew_count = #{renewCount}
WHERE id = #{id}

UPDATE loan
SET status       = 2,
    overdue_days = #{overdueDays},
    fine         = #{fine}
WHERE id = #{id}

mapper.select:
SELECT b.title AS bookTitle, b.author AS author, COUNT(*) AS borrowCount FROM loan l LEFT JOIN book_copy c ON l.copy_id = c.id LEFT JOIN book b ON c.book_id = b.id
b.id IS NOT NULL AND l.borrowed_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)
GROUP BY b.id, b.title, b.author ORDER BY borrowCount DESC LIMIT #{limit}
